import{_ as e,o,c as a,a2 as r}from"./chunks/framework.CfwCq2QB.js";const d="/dev-go-docs/shots/0.2.3/zh-CN/light/options-general.png",s="/dev-go-docs/shots/0.2.3/zh-CN/dark/options-general.png",_=JSON.parse('{"title":"通用与外观","description":"","frontmatter":{},"headers":[],"relativePath":"settings/general.md","filePath":"settings/general.md"}'),n={name:"settings/general.md"};function l(i,t,c,h,g,p){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="通用与外观" tabindex="-1">通用与外观 <a class="header-anchor" href="#通用与外观" aria-label="Permalink to &quot;通用与外观&quot;">​</a></h1><p>一句话：主题、界面语言、弹窗默认页、快捷键、跨设备同步与数据备份，都在设置页「通用」里。</p><h2 id="外观" tabindex="-1">外观 <a class="header-anchor" href="#外观" aria-label="Permalink to &quot;外观&quot;">​</a></h2><ul><li><strong>主题</strong>：浅色 / 深色 / 自动。自动指 18:00 – 6:00 使用深色；弹窗、设置页、侧边栏与新标签页统一生效</li><li><strong>界面语言</strong>：跟随浏览器 / 中文 / English。切换立即生效，已经打开的页面不用刷新；扩展名称和快捷键说明由浏览器按自身语言显示（读的是 manifest，手动切换管不到）</li></ul><img src="'+d+'" alt="通用设置"><img src="'+s+'" alt="深色通用设置"><h2 id="弹窗" tabindex="-1">弹窗 <a class="header-anchor" href="#弹窗" aria-label="Permalink to &quot;弹窗&quot;">​</a></h2><p><strong>默认打开的页</strong>：点工具栏图标或按 <code>Alt+1</code> 打开弹窗时定位到哪一页（翻译 / 网络 / 资源 / 功能）。网络和资源还有专属快捷键 <code>Alt+3</code> / <code>Alt+4</code>。</p><h2 id="快捷键" tabindex="-1">快捷键 <a class="header-anchor" href="#快捷键" aria-label="Permalink to &quot;快捷键&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>默认键</th></tr></thead><tbody><tr><td>打开弹窗（默认页）</td><td><code>Alt+1</code></td></tr><tr><td>打开 AI 助手（侧边栏）</td><td><code>Alt+2</code>（Chrome 专有）</td></tr><tr><td>打开弹窗「网络」页</td><td><code>Alt+3</code></td></tr><tr><td>打开弹窗「资源」页</td><td><code>Alt+4</code></td></tr><tr><td>整页行间翻译</td><td>未绑定，可自行绑定</td></tr></tbody></table><p>浏览器不允许扩展自行修改快捷键：</p><ul><li><strong>Chrome / Edge</strong>：在 <code>chrome://extensions/shortcuts</code> 里改，改完回到设置页会自动刷新显示</li><li><strong>Firefox</strong>：<code>about:addons</code> 右上角齿轮 →「管理扩展快捷键」</li></ul><h2 id="跨设备同步" tabindex="-1">跨设备同步 <a class="header-anchor" href="#跨设备同步" aria-label="Permalink to &quot;跨设备同步&quot;">​</a></h2><p>快捷导航、代理配置会随浏览器账号自动同步到其他设备（Chrome 同步空间上限 100KB，这里会显示用量）。「立即同步」手动触发一次，同时显示上次同步时间。</p><h2 id="数据备份" tabindex="-1">数据备份 <a class="header-anchor" href="#数据备份" aria-label="Permalink to &quot;数据备份&quot;">​</a></h2><p><strong>导出配置</strong>生成 JSON 文件（快捷导航、网络、翻译、AI 模型、划词动作等全部设置）；<strong>导入配置</strong>恢复。API Key <strong>不会</strong>写入备份文件，换机后需要重新填写。详见<a href="/dev-go-docs/settings/sync.html">备份与同步</a>。</p>',16)])])}const u=e(n,[["render",l]]);export{_ as __pageData,u as default};
